API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("API Gateway", "API Gateway") {
    Component("Claims-Driven Geo-Routing Filter", "Claims-Driven Geo-Routing Filter", "Envoy-based Cloud Endpoints / Apigee", "Routes client requests based on geographic claims and regional data residency constraints.")
    Component("Consent & Policy Enforcement Filter", "Consent & Policy Enforcement Filter", "Envoy-based Cloud Endpoints / Apigee", "Enforces consent validation and policy checks for cross-border health data access.")
    Component("Telemetry & Resilience Proxy", "Telemetry & Resilience Proxy", "Envoy-based Cloud Endpoints / Apigee", "Handles telemetry tracking and resilience proxying for downstream microservices.")
}

Rel("Claims-Driven Geo-Routing Filter", "Consent & Policy Enforcement Filter", "Internal gRPC")
Rel("Consent & Policy Enforcement Filter", "Telemetry & Resilience Proxy", "Internal gRPC")
@enduml

Core Telehealth Backend.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(core_telehealth_backend, "Core Telehealth Backend") {
    Component(Transaction_Ingestion_Component, "Transaction Ingestion Component", "Go / gRPC", "Ingests transaction payloads securely with idempotency keys.")
    Component(Resilient_Sync_Orchestrator, "Resilient Sync Orchestrator", "Go / Temporal on GKE", "Manages offline-resilient transactions and workflow orchestration.")
    Component(Session_State_Manager, "Session & State Manager", "Go / Redis Memorystore", "Handles real-time session and state management.")
    Component(Clinical_Exception_Audit_Notifier, "Clinical Exception & Audit Notifier", "Go / GCP Pub/Sub", "Dispatches failure events and audit notifications via regional topics.")
}

Rel(Transaction_Ingestion_Component, Resilient_Sync_Orchestrator, "Passes idempotency-keyed payloads securely")
Rel(Resilient_Sync_Orchestrator, Clinical_Exception_Audit_Notifier, "Dispatches failure events via GCP Pub/Sub regional topics")

@enduml

Video Streaming Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(Core_Telehealth_Backend, "Core Telehealth Backend", "External container for telemetry data collection")

Container_Boundary(Video_Streaming_Gateway, "Video Streaming Gateway") {
    Component(SFU_Media_Router_Component, "SFU Media Router Component", "MediaSoup C++/Node.js", "Core SFU media routing for high-performance packet forwarding and WebRTC media transport.")
    Component(Adaptive_Bitrate___Transcoding_Controller_Component, "Adaptive Bitrate & Transcoding Controller Component", "Internal IPC / gRPC", "Handles dynamic media layer adjustments to maintain consultations in degraded network conditions.")
    Component(Signaling___Session_Manager_Component, "Signaling & Session Manager Component", "Node.js/Go", "Manages WSS signaling and real-time room orchestration using short-lived JWTs.")
    Component(Media_Telemetry_Exporter_Component, "Media Telemetry Exporter Component", "Prometheus scrape protocol", "Exports session quality metrics for real-time telemetry.")
}

Rel(Adaptive_Bitrate___Transcoding_Controller_Component, SFU_Media_Router_Component, "Dynamic media layer adjustments", "Internal IPC / gRPC")
Rel(Media_Telemetry_Exporter_Component, Core_Telehealth_Backend, "HTTP Prometheus scrape protocol for session quality metrics", "HTTP")
@enduml
